const job = items[0].json;
const now = new Date().toISOString();
const workflowName = (job.workflow && job.workflow.name) ? job.workflow.name : 'unknown';
const errMsgRaw = job.execution && job.execution.error ? job.execution.error : null;
const errMsg = errMsgRaw ? (errMsgRaw.message || String(errMsgRaw)) : 'Unknown error';
const errNode = (job.execution && job.execution.lastNodeExecuted) ? job.execution.lastNodeExecuted : null;

const subject = 'Pipeline error: ' + workflowName;
const body = 'Workflow: ' + workflowName + '\n' +
  'Failed node: ' + (errNode || 'unknown') + '\n' +
  'Error: ' + errMsg + '\n' +
  'Time: ' + now;

return [{ json: { subject: subject, body: body } }];
